// Base64-embedded logos/seal for the printable payment receipt (expo-print
// renders the HTML in an isolated WebView, so local file:// asset paths
// don't reliably resolve there — inline data URIs are the dependable route).
// Kiranam mark: stacked wordmark with the background plate removed and the
// glyphs recolored red (derived from kiranam-admin/brand/logo/wordmark-stacked.svg).
export const KIRANAM_LOGO_DATA_URI = 'data:image/png;base64,';
export const HCF_LOGO_DATA_URI = 'data:image/png;base64,';
export const HCF_SEAL_DATA_URI = 'data:image/png;base64,';
